 150               <div className="flex items-center gap-1 px-1">
 151                 <Button variant="ghost" size="sm" className="h-8 text-[9px] font-black uppercase tracking-widest px-2 rounded-lg" onClick={() => editor.chain().focus().addColumnBefore().run()}>+ Col</Button>
 152                 <Button variant="ghost" size="sm" className="h-8 text-[9px] font-black uppercase tracking-widest px-2 rounded-lg" onClick={() => editor.chain().focus().addRowBefore().run()}>+ Row</Button>
 153               </div>
 154               <div className="h-4 w-px bg-primary/10" />
 155               <Button
 156                 variant="ghost"
 157                 size="sm"
 158                 className="h-8 text-[9px] font-black uppercase tracking-widest px-2 rounded-lg text-destructive hover:bg-destructive/10 hover:text-destructive"
 159                 onClick={() => editor.chain().focus().deleteTable().run()}
 160               >
 161                 Delete Table
 162               </Button>
 163             </div>
 164           ) : (
 165             <ContextualToolbar editor={editor as Editor} />
 166           )}
 167         </BubbleMenu>
 168       )}
 169       <div
